<?php
namespace App\Http\Controllers;
use App\Models\{Inquiry,User,Activity};
use App\Http\Requests\InquiryRequest;
use App\Services\PublicSubmissions;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class InquiryController extends Controller {
 public function store(InquiryRequest $r,PublicSubmissions $submissions){$submissions->inquiry($r,$r->validated());return $r->expectsJson()?response()->json(['message'=>'Thank you. Your request has been received. The centre will contact you; this is not a confirmed appointment.'],201):redirect()->route('contact')->with('success','Your request has been received. The centre will contact you; this is not a confirmed appointment.');}
 private function access(Request $r):void{abort_unless($r->user()?->canManageInquiries(),403);}
 public function index(Request $r){$this->access($r);$q=Inquiry::with(['service','assignee']);if($r->status==='trash')$q->onlyTrashed();elseif(in_array($r->status,['new','contacted','in_progress','closed','spam'],true))$q->where('status',$r->status);foreach(['interest','session_preference','source'] as $filter)if($r->filled($filter))$q->where($filter,mb_substr((string)$r->$filter,0,60));if($r->filled('reference'))$q->where('reference',$r->validate(['reference'=>['regex:/^VCC-[A-Z0-9]{1,16}$/']])['reference']);if($r->filled('assigned_to'))$q->where('assigned_to',$r->integer('assigned_to'));\App\Services\DateFilters::apply($q,$r,'created_at');return view('centre.inquiries',['items'=>$q->latest()->paginate(15)->withQueryString(),'staff'=>User::where('active',true)->where(fn($q)=>$q->where('role','administrator')->orWhere('can_manage_inquiries',true))->get()]);}
 public function show(Request $r,Inquiry $inquiry){$this->access($r);return response()->view('centre.inquiry-show',['inquiry'=>$inquiry->load(['service','assignee','followups.user']),'staff'=>User::where('active',true)->where(fn($q)=>$q->where('role','administrator')->orWhere('can_manage_inquiries',true))->get()])->header('Cache-Control','no-store, private')->header('Referrer-Policy','no-referrer');}
 public function update(Request $r,Inquiry $inquiry){$this->access($r);$d=$r->validate(['status'=>['required','in:new,contacted,in_progress,closed,spam'],'assigned_to'=>['nullable','integer','exists:users,id'],'note'=>['nullable','string','max:4000']]);if(!empty($d['assigned_to']))abort_unless(User::find($d['assigned_to'])?->canManageInquiries(),422);DB::transaction(function()use($r,$inquiry,$d){$inquiry->status=$d['status'];$inquiry->assigned_to=$d['assigned_to']??null;if($d['status']==='contacted'&&!$inquiry->contacted_at)$inquiry->contacted_at=now();if($d['status']==='closed')$inquiry->closed_at=now();$inquiry->save();$inquiry->followups()->create(['user_id'=>$r->user()->id,'action'=>'Status / assignment updated','note'=>$d['note']??null]);Activity::record('Inquiry updated','Inquiry #'.$inquiry->id);});return back()->with('success','Inquiry updated. Follow-up notes remain private.');}
 public function destroy(Request $r,Inquiry $inquiry){$this->access($r);abort_unless($r->user()->isAdministrator(),403);$inquiry->delete();Activity::record('Inquiry archived','Inquiry #'.$inquiry->id);return redirect()->route('inquiries.index')->with('success','Inquiry archived.');}
 public function restore(Request $r,int $inquiry){abort_unless($r->user()->isAdministrator(),403);Inquiry::onlyTrashed()->findOrFail($inquiry)->restore();return back()->with('success','Inquiry restored.');}
 public function redact(Request $r,Inquiry $inquiry){abort_unless($r->user()->isAdministrator(),403);$r->validate(['confirm'=>['required','in:REDACT']]);DB::transaction(function()use($inquiry){$inquiry->forceFill(['full_name'=>'[redacted]','email'=>'[redacted]','mobile'=>'[redacted]','message'=>null,'preferred_window'=>null,'redacted_at'=>now(),'status'=>'closed','closed_at'=>now()])->save();$inquiry->followups()->update(['note'=>null]);Activity::record('Inquiry personal data redacted','Inquiry #'.$inquiry->id);});return back()->with('success','Personal data and follow-up notes permanently redacted. Encrypted backups follow your backup retention policy.');}
}
